        return []

    # If b is empty, just return merged a
    if not b:
        return merge_intervals(a)

    # Merge both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_start = a_start
        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after current interval
                break

            # b interval overlaps with current position
            if b_start > current_start:
                # Add the part before b starts
                result.append([current_start, b_start])

            # Move current_start to after b ends
            current_start = max(current_start, b_end)

        # Add remaining part if any
        if current_start < a_end:
            result.append([current_start, a_end])

    return result


def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start, then by end
    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0]]
    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # No overlap - add as new interval
            merged.append([current_start, current_end])

    return merged

